#define POL_EF 0x12F0000000000000ull
#define POL_EL 0x14F0000000000000ull
__device__ __forceinline__ float silu_bw(float g, float x, float s) {
    return __fmul_rn(g, __fmul_rn(s, __fadd_rn(1.0f, __fmul_rn(x, __fsub_rn(1.0f, s)))));}
__device__ __forceinline__ float4 ld4(const float* p) { float4 v;
  asm volatile("ld.global.L2::cache_hint.v4.f32 {%0,%1,%2,%3}, [%4], %5;" : "=f"(v.x),"=f"(v.y),"=f"(v.z),"=f"(v.w) : "l"(p), "l"(POL_EF)); return v;}
__device__ __forceinline__ void st4(float* p, float4 v) {
  asm volatile("st.global.L2::cache_hint.v4.f32 [%0], {%1,%2,%3,%4}, %5;" :: "l"(p),"f"(v.x),"f"(v.y),"f"(v.z),"f"(v.w),"l"(POL_EL) : "memory");}
template<int MODE> __device__ __forceinline__ void body(const float* g, const float* x, const float* s, float* o, unsigned n, int flag) {
  unsigned nvec = n >> 2; unsigned i = blockIdx.x * 256 + threadIdx.x;
  if (MODE == 0) return;
  if (i < nvec) {
    if (MODE == 3) { float f = (float)i; st4(o + 4*i, make_float4(f,f,f,f)); return; }
    float4 a = ld4(g+4*i), b = ld4(x+4*i), c = ld4(s+4*i); float4 r;
    r.x = silu_bw(a.x,b.x,c.x); r.y = silu_bw(a.y,b.y,c.y); r.z = silu_bw(a.z,b.z,c.z); r.w = silu_bw(a.w,b.w,c.w);
    if (MODE == 2 || flag) st4(o + 4*i, r);
  } else if (i == nvec) {
    unsigned e = nvec << 2;
    for (int k = 0; k < 3; ++k) if (e + k < n) { float v = (MODE==3) ? 1.f : silu_bw(g[e+k], x[e+k], s[e+k]); if (MODE != 1 || flag) o[e+k] = v; }
  }
}
extern "C" __global__ void __cluster_dims__(2,1,1) __launch_bounds__(256) k_empty(const float* g, const float* x, const float* s, float* o, unsigned n, int f) { body<0>(g,x,s,o,n,f); }
