__device__ __forceinline__ float silu_bw(float g, float x, float s) {
    return __fmul_rn(g, __fmul_rn(s, __fadd_rn(1.0f, __fmul_rn(x, __fsub_rn(1.0f, s)))));}
template<int L> __device__ __forceinline__ float4 ld4(const float* p) { float4 v;
  if (L==0) asm volatile("ld.global.L2::cache_hint.v4.f32 {%0,%1,%2,%3}, [%4], %5;" : "=f"(v.x),"=f"(v.y),"=f"(v.z),"=f"(v.w) : "l"(p), "l"(POL_EF));
  if (L==1) asm volatile("ld.global.nc.L1::no_allocate.L2::cache_hint.v4.f32 {%0,%1,%2,%3}, [%4], %5;" : "=f"(v.x),"=f"(v.y),"=f"(v.z),"=f"(v.w) : "l"(p), "l"(POL_EF));
  if (L==2) asm volatile("ld.global.cv.v4.f32 {%0,%1,%2,%3}, [%4];" : "=f"(v.x),"=f"(v.y),"=f"(v.z),"=f"(v.w) : "l"(p));
