  return v;}
template<int S> __device__ __forceinline__ void st4(float* p, float4 v) {
  if (S==0) asm volatile("st.global.L2::cache_hint.v4.f32 [%0], {%1,%2,%3,%4}, %5;" :: "l"(p),"f"(v.x),"f"(v.y),"f"(v.z),"f"(v.w),"l"(POL_EL) : "memory");
  if (S==1) asm volatile("st.global.wt.v4.f32 [%0], {%1,%2,%3,%4};" :: "l"(p),"f"(v.x),"f"(v.y),"f"(v.z),"f"(v.w) : "memory");
  if (S==2) asm volatile("st.global.cs.v4.f32 [%0], {%1,%2,%3,%4};" :: "l"(p),"f"(v.x),"f"(v.y),"f"(v.z),"f"(v.w) : "memory");
  if (S==3) asm volatile("st.global.v4.f32 [%0], {%1,%2,%3,%4};" :: "l"(p),"f"(v.x),"f"(v.y),"f"(v.z),"f"(v.w) : "memory");
