}
template<int L, int S, int ONE> __device__ __forceinline__ void body(const float* g, const float* x, const float* s, float* o, unsigned n) {
  unsigned nvec = n >> 2; unsigned i = blockIdx.x * blockDim.x + threadIdx.x;
