__device__ __forceinline__ void bulk_g2s(float* sdst, const float* gsrc, unsigned bytes, unsigned bar) {
  unsigned d = (unsigned)__cvta_generic_to_shared(sdst);
  asm volatile("cp.async.bulk.shared::cta.global.mbarrier::complete_tx::bytes.L2::cache_hint [%0], [%1], %2, [%3], %4;"
     :: "r"(d), "l"(gsrc), "r"(bytes), "r"(bar), "l"(POL_EF) : "memory");
}
template<int BST> __device__ __forceinline__ void bulk_body(const float* g, const float* x, const float* s, float* o, unsigned n) {
  __shared__ __align__(128) float sg[1024]; __shared__ __align__(128) float sx[1024]; __shared__ __align__(128) float ss[1024];
  __shared__ __align__(8) unsigned long long bar;
  unsigned nvec = n >> 2;
  unsigned base = blockIdx.x * 1024u;              // float offset
  unsigned nb = 4u * nvec;                          // floats in vector body
  unsigned cnt = base < nb ? min(1024u, nb - base) : 0u;
  unsigned b = (unsigned)__cvta_generic_to_shared(&bar);
  if (threadIdx.x == 0 && cnt) {
    asm volatile("mbarrier.init.shared::cta.b64 [%0], 1;" :: "r"(b));
    asm volatile("fence.mbarrier_init.release.cluster;" ::: "memory");
    asm volatile("mbarrier.arrive.expect_tx.shared::cta.b64 _, [%0], %1;" :: "r"(b), "r"(cnt * 12u) : "memory");
    bulk_g2s(sg, g + base, cnt*4u, b); bulk_g2s(sx, x + base, cnt*4u, b); bulk_g2s(ss, s + base, cnt*4u, b);
  }
  unsigned i = blockIdx.x * 256 + threadIdx.x;
  // tail thread: plain loads
  if (i == nvec) { unsigned e = nvec << 2; for (int k = 0; k < 3; ++k) if (e + k < n) o[e+k] = silu_bw(g[e+k], x[e+k], s[e+k]); }
  if (!cnt) return;
  __syncthreads();
  asm volatile("{ .reg .pred p; WAIT_%=: mbarrier.try_wait.parity.shared::cta.b64 p, [%0], 0; @!p bra WAIT_%=; }" :: "r"(b) : "memory");
  unsigned j = threadIdx.x * 4;
  if (j < cnt) {
    float4 a = *(float4*)&sg[j], bb = *(float4*)&sx[j], c = *(float4*)&ss[j]; float4 r;
    r.x = silu_bw(a.x,bb.x,c.x); r.y = silu_bw(a.y,bb.y,c.y); r.z = silu_bw(a.z,bb.z,c.z); r.w = silu_bw(a.w,bb.w,c.w);
    if (BST) *(float4*)&sg[j] = r; else st4<0>(o + base + j, r);
  }
  if (BST) {
    asm volatile("fence.proxy.async.shared::cta;" ::: "memory");
    __syncthreads();
    if (threadIdx.x == 0) {
      unsigned sa = (unsigned)__cvta_generic_to_shared(sg);
      asm volatile("cp.async.bulk.global.shared::cta.bulk_group.L2::cache_hint [%0], [%1], %2, %3;" :: "l"(o + base), "r"(sa), "r"(cnt*4u), "l"(POL_EL) : "memory");
      asm volatile("cp.async.bulk.commit_group;" ::: "memory");
      asm volatile("cp.async.bulk.wait_group.read 0;" ::: "memory");
    }
  }
}
